import {initialState,advance,standings,nextDate,periodKey,isSeason,offerContract,marketSalary,adoptPolicy,borrow,serialize,deserialize,TEAM_NAMES} from './lib/engine.js';
import {METRICS,PLAYER_METRICS,query,latestMetrics,playerMetrics,RULES} from './lib/semantic.js';
import {advisorContext,forecast,advisorProvider} from './lib/advisor.js';
const KEY='komorebi-gm-v1', app=document.querySelector('#app');
let state, page='dashboard', draft, advice=null, selectedMonth, selectedYear, tab='club', busy=false, saveStatus='自動保存 ON';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{state=localStorage.getItem(KEY)?deserialize(localStorage.getItem(KEY)):initialState();}catch{state=initialState();saveStatus='保存データを読めませんでした。新規状態で開始';}
draft=structuredClone(state.policy);
const wan=n=>n==null?'—':(n/10000).toLocaleString('ja-JP',{maximumFractionDigits:Math.abs(n)<10000?4:0});
const num=n=>n==null?'—':n.toLocaleString('ja-JP',{maximumFractionDigits:0});
const money=n=>`${wan(n)}<small>万円</small>`;
const signed=n=>`${n>=0?'+':''}${wan(n)}`;
const fmt=(value,unit)=>value==null?'—':unit==='円'?`${wan(value)} 万円`:unit==='%'?`${(value*100).toFixed(1)}%`:unit==='回'?`${value.toFixed(2)} 回`:`${num(value)} ${unit}`;
const icon=(name,size=20)=>{
  const paths={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 5a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',sliders:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',chart:'<path d="M4 3v17h17M8 16v-5m5 5V7m5 9V4"/>',trophy:'<path d="M8 3h8v6a4 4 0 0 1-8 0ZM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4m-4 1v7m-4 0h8"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4m-2-2h4"/>',history:'<path d="M3 10a9 9 0 1 1 1 7M3 4v6h6m3-4v6l4 2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',book:'<path d="M3 4h7l2 2 2-2h7v16h-7l-2 1-2-1H3ZM12 6v15"/>',save:'<path d="M4 3h13l4 4v14H3V3Zm3 0v7h10V3M7 21v-7h10v7"/>',leaf:'<path d="M4 20 18 6M5 17C-1 5 11 2 21 3c0 10-2 17-11 16"/>',cash:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M17 12h4"/><circle cx="16" cy="12" r="1"/>',ball:'<circle cx="12" cy="12" r="9"/><path d="M5 5c7 4 7 10 0 14m14-14c-7 4-7 10 0 14"/>'};
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.ball}</svg>`;
};
const bear=(size=58)=>`<svg width="${size}" height="${size}" viewBox="0 0 80 80" aria-hidden="true"><circle cx="19" cy="25" r="12" fill="#b77e50"/><circle cx="61" cy="25" r="12" fill="#b77e50"/><ellipse cx="40" cy="45" rx="30" ry="28" fill="#c99567"/><ellipse cx="40" cy="55" rx="15" ry="12" fill="#f8e2bd"/><circle cx="29" cy="43" r="3" fill="#453c32"/><circle cx="51" cy="43" r="3" fill="#453c32"/><ellipse cx="40" cy="52" rx="5" ry="3.5" fill="#453c32"/><path d="M40 55v5m-5-1q5 6 10 0" fill="none" stroke="#453c32" stroke-width="2" stroke-linecap="round"/><path d="M17 29Q19 4 43 9q19 2 21 23Z" fill="#306450"/><path d="M17 29q21-6 49 2l5 5H18Z" fill="#214a3a"/><text x="36" y="25" font-size="14" font-weight="bold" fill="#f9efce">K</text><circle cx="20" cy="52" r="4" fill="#dd967d" opacity=".6"/><circle cx="60" cy="52" r="4" fill="#dd967d" opacity=".6"/></svg>`;
const metricButton=id=>`<button class="info" data-metric="${id}" aria-label="${METRICS[id].name}の計算方法">i</button>`;
const empty=(title,desc)=>`<div class="empty">${icon('leaf',36)}<h3>${title}</h3><p>${desc}</p></div>`;
function persist(){try{localStorage.setItem(KEY,serialize(state));saveStatus='保存済み · このブラウザ';}catch{saveStatus='保存できません。JSONを書き出してください';toast(saveStatus);}}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4200);}
function header(title,desc,eyebrow='CLUB MANAGEMENT'){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><span class="date-chip">${icon('ball')} ${state.year}年 ${state.month}月 <b>${isSeason(state.month)?'シーズン中':'オフシーズン'}</b></span></div>`;}
function render(){
 const d=nextDate(state), menus=[['dashboard','home','経営ダッシュボード'],['roster','people','選手・契約'],['plan','sliders','経営プラン'],['finance','chart','月次決算'],['season','trophy','シーズン成績'],['advisor','spark','AI参謀'],['history','history','施策ノート']];
 app.innerHTML=`<aside class="sidebar"><a class="brand" href="#" data-page="dashboard"><span class="brand-mark">${icon('ball',30)}</span><span>こもれび<em>球団経営室</em></span></a><div class="club-card">${bear(48)}<div><strong>こもれびベアーズ</strong><span>オーナー / GM</span></div></div><p class="nav-label">YOUR CLUB</p><nav>${menus.map(([id,i,label])=>`<button class="${page===id?'active':''}" data-page="${id}">${icon(i)}<span>${label}</span>${id==='advisor'?'<span class="tiny-dot"></span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="season-note">${icon('leaf')}<span>強い球団を、<br>ながく愛される球団に。</span></div><button class="sub-nav" data-action="rules">${icon('book')} 指標とゲームのルール</button><div class="save-state"><span></span>${esc(saveStatus)}</div></div></aside>
 <div class="workspace"><header class="topbar"><div class="breadcrumb">KOMOREBI BASEBALL CLUB <span>/</span> オーナーズデスク</div><div class="top-actions"><button class="icon-button" data-action="rules" title="ゲームのルール" aria-label="ゲームのルール">${icon('book')}</button><button class="icon-button" data-action="new-game" title="はじめから遊ぶ" aria-label="はじめから遊ぶ">${icon('leaf')}</button><button class="icon-button" data-action="export" title="セーブを書き出す" aria-label="セーブを書き出す">${icon('save')}</button><button class="icon-button" data-action="import" title="セーブを読み込む" aria-label="セーブを読み込む">${icon('history')}</button><span class="owner">GM</span></div></header><main>${({dashboard,roster,plan,finance,season,advisor,history})[page]()}</main><footer><span>${icon('leaf',16)} 数字の向こうに、球団の未来。</span><span>すべて架空の球団・選手です · 金額：万円（単価を除く）</span></footer></div>`;
 bind();
}
function trendChart(){
 const rows=state.months.slice(-8);if(!rows.length)return empty('最初の1か月を、ここから。','経営プランを設定して4月へ進むと、売上と利益の推移が描かれます。');
 const values=rows.flatMap(r=>[query(state,{metric:'revenue',from:r.id,to:r.id}).value,query(state,{metric:'operatingProfit',from:r.id,to:r.id}).value]);
 const hi=Math.max(...values,10000000)*1.15,lo=Math.min(...values,0)*1.2, y=v=>170-(v-lo)/(hi-lo)*145,x=i=>65+i*(550/Math.max(rows.length-1,1));
 const points=id=>rows.map((r,i)=>`${x(i)},${y(query(state,{metric:id,from:r.id,to:r.id}).value)}`).join(' ');
 return `<svg viewBox="0 0 660 215" class="trend-chart" role="img" aria-label="売上高と営業利益の月次推移">${[0,.5,1].map(k=>{const v=lo+(hi-lo)*k;return `<line x1="60" x2="635" y1="${y(v)}" y2="${y(v)}" stroke="#eceee7"/><text x="48" y="${y(v)+4}" text-anchor="end">${wan(v)}</text>`;}).join('')}<polyline points="${points('revenue')}" stroke="#39785f" fill="none" stroke-width="3" stroke-linejoin="round"/><polyline points="${points('operatingProfit')}" stroke="#e1a057" fill="none" stroke-width="3" stroke-linejoin="round"/>${rows.map((r,i)=>`<circle cx="${x(i)}" cy="${y(query(state,{metric:'revenue',from:r.id,to:r.id}).value)}" r="4" fill="#39785f"/><circle cx="${x(i)}" cy="${y(query(state,{metric:'operatingProfit',from:r.id,to:r.id}).value)}" r="4" fill="#e1a057"/><text x="${x(i)}" y="201" text-anchor="middle">${r.month}月</text>`).join('')}</svg>`;
}
function field(){
return `<svg viewBox="0 0 440 250" class="field" role="img" aria-label="木々に囲まれたこもれび球場のイラスト"><ellipse cx="220" cy="227" rx="172" ry="13" fill="#d8e2bc" opacity=".6"/><path d="M67 110Q220-23 373 110L220 233Z" fill="#a4bf92"/><path d="M82 111Q220-7 358 111L220 220Z" fill="#bed2a3"/><path d="m95 113 125 99 125-99M118 96l102 89L322 96M146 81l74 68 74-68" fill="none" stroke="#b0c797" stroke-width="21"/><path d="m220 202-63-55 63-56 63 56Z" fill="#ead7ac"/><path d="m220 184-43-37 43-39 43 39Z" fill="#9bb88a"/><path d="m220 202-123-97m123 97 123-97" fill="none" stroke="#fff7e4" stroke-width="2"/><path d="m220 196 5 5-5 5-5-5Zm-62-54 7 4-4 7-7-4Zm62-57 5 5-5 5-5-5Zm59 57 7 4-4 7-7-4Z" fill="#fffdf1"/><ellipse cx="220" cy="147" rx="10" ry="7" fill="#ead7ac"/><circle cx="220" cy="145" r="3" fill="#fffdf1"/><path d="M64 106Q220-35 376 106" fill="none" stroke="#f6f0d9" stroke-width="10"/><rect x="179" y="18" width="82" height="34" rx="4" fill="#426952"/><text x="220" y="31" fill="#f4edca" text-anchor="middle" font-size="7" letter-spacing="2">KOMOREBI</text><text x="220" y="44" fill="#f4edca" text-anchor="middle" font-size="9">PLAY BALL!</text>${[[51,117],[378,126],[81,76],[347,72],[111,51],[322,44]].map(([x,y])=>`<path d="M${x} ${y}v22" stroke="#9e8f69" stroke-width="5"/><circle cx="${x}" cy="${y-6}" r="15" fill="#769b75"/><circle cx="${x-6}" cy="${y-12}" r="11" fill="#89aa7d"/>`).join('')}<path d="M119 183v22m201-22v22" stroke="#afbc9f" stroke-width="3"/><rect x="108" y="178" width="23" height="10" rx="2" fill="#fff9e8"/><rect x="309" y="178" width="23" height="10" rx="2" fill="#fff9e8"/><circle cx="220" cy="174" r="5" fill="#48715b"/><circle cx="179" cy="142" r="4" fill="#48715b"/><circle cx="270" cy="111" r="4" fill="#48715b"/><circle cx="181" cy="83" r="4" fill="#48715b"/><circle cx="220" cy="147" r="4" fill="#c3855d"/></svg>`;
}
function dashboard(){
 const m=latestMetrics(state), table=standings(state), team=table.find(r=>r.id===0), rank=table.indexOf(team)+1,last=state.months.at(-1),d=nextDate(state);
 const prev=state.months.at(-2), delta=prev&&last?query(state,{metric:'revenue',from:last.id,to:last.id}).value-query(state,{metric:'revenue',from:prev.id,to:prev.id}).value:null;
 const data=advice||null;
 return `${header('おかえりなさい、オーナー。','今日のひとつの判断が、明日のベアーズを育てます。')}
 <section class="hero"><div class="hero-copy"><span class="pill light">${icon('leaf',14)} OUR NEXT CHAPTER</span><h2>球団の未来を、<br>いっしょに育てよう。</h2><p>勝利も、健全な経営も。<br>データと小さな工夫で、愛される球団へ。</p><button class="primary" data-action="advance">${d.month}月へ進む ${icon('arrow',17)}</button><span class="hero-note">1ターン＝1か月 · 進行時に自動保存</span></div><div class="hero-visual">${field()}<div class="stadium-label"><span class="live-dot"></span> こもれびパーク <span>24,000 席</span></div></div></section>
 <div class="kpi-grid"><article class="kpi"><div class="kpi-label">現金残高 ${metricButton('cash')}</div><strong class="${state.cash<0?'negative':''}">${money(state.cash)}</strong><span>${icon('cash',14)} ${state.debt?'借入残高 '+wan(state.debt)+' 万円':'持続可能な経営のために'}</span></article>
 <article class="kpi"><div class="kpi-label">今月の売上高 ${metricButton('revenue')}</div><strong>${money(m.revenue.value)}</strong><span class="${delta!=null&&delta>=0?'positive':''}">${delta==null?(last?'前月の比較データはありません':'最初の決算を待っています'):`${delta>=0?'↗':'↘'} 前月比 ${signed(delta)} 万円`}</span></article>
 <article class="kpi"><div class="kpi-label">今月の営業利益 ${metricButton('operatingProfit')}</div><strong class="${m.operatingProfit.value<0?'negative':'green'}">${money(m.operatingProfit.value)}</strong><span>営業利益率 ${fmt(m.margin.value,'%')}</span></article>
 <article class="kpi"><div class="kpi-label">リーグ順位 <span class="mini-icon">${icon('trophy',16)}</span></div><strong>${team.w+team.l?rank:'—'}<small>位 / 4球団</small></strong><span>${team.w}勝 ${team.l}敗 <i>·</i> ${team.w+team.l?`勝率 ${(team.w/(team.w+team.l)).toFixed(3)}`:'開幕を楽しみに'}</span></article></div>
 <div class="dashboard-grid"><section class="card revenue-card"><div class="section-heading"><div><h2>球団の経営レポート</h2><p>毎月の積み重ねを、数字で見よう。</p></div><button class="text-button" data-page="finance">決算を見る ${icon('arrow',15)}</button></div><div class="chart-legend"><span><i class="legend-dot green-bg"></i>売上高</span><span><i class="legend-dot orange-bg"></i>営業利益</span><small>単位：万円</small></div>${trendChart()}</section>
 <section class="card advisor-card"><div class="advisor-heading"><span class="advisor-avatar">${icon('spark',24)}</span><div><h2>AI参謀のひとこと</h2><span class="demo-label">ルールベースのデモ</span></div><span class="status-dot"></span></div><span class="eyebrow">NEXT BEST MOVE</span><h3>${data?esc(data.title):'まずは、在庫と現金のバランスから。'}</h3><p>${data?esc(data.action):'最初の経営プランを立てましょう。仕入れは資金を使い、売れた分だけが費用になります。'}</p><div class="advisor-footnote">${icon('book',15)} 共通の指標定義から分析します</div><button class="secondary full" data-page="advisor">参謀に相談する ${icon('arrow',17)}</button></section>
 <section class="card"><div class="section-heading"><div><h2>クラブのコンディション</h2><p>数字に映る、球団のいま。</p></div>${icon('leaf',22)}</div><div class="condition"><span>ファンの熱量</span><b>${Math.round(state.fans)}<small> / 100</small></b><div class="progress"><i style="width:${state.fans}%"></i></div></div><div class="condition"><span>球場のにぎわい ${metricButton('occupancy')}</span><b>${fmt(m.occupancy.value,'%')}</b><div class="progress gold"><i style="width:${(m.occupancy.value||0)*100}%"></i></div></div><div class="condition-bottom"><span>所属選手 <b>${state.players.filter(p=>p.team===0).length}人</b></span><span>残り在庫 <b>${num(state.products.reduce((n,p)=>n+p.stock,0))}個</b></span></div></section>
 <section class="card voices"><div class="section-heading"><div><h2>球場からの声</h2><p>ベアーズを支える、みんなの気持ち。</p></div><span>☀</span></div><div class="voice"><span class="voice-avatar peach">☺</span><div><b>いつものファン <small>FAN</small></b><p>「${state.policy.ticket>3600?'応援したいけど、毎週のチケットはちょっと高いな。':state.fans>65?'この球団、最近いい雰囲気！また友だちを連れてくるね。':'今度の週末も、こもれびパークで会おうね。'}」</p></div></div><div class="voice"><span class="voice-avatar sage">${icon('ball',23)}</span><div><b>${esc(state.players.find(p=>p.team===0)?.name)} <small>PLAYER</small></b><p>「${state.policy.training>=5000000?'じっくり練習できる環境、ありがたいです。次の一勝に向けて！':'練習環境をもう少し充実させたい。ここから強くなろう。'}」</p></div></div></section></div>
 ${state.notices.length?`<section class="notice">${state.notices.map(n=>`<p>${esc(n)}</p>`).join('')}</section>`:''}`;
}
function roster(){
 const list=tab==='market'?state.freeAgents:state.players.filter(p=>p.team===0),off=!isSeason(state.month);
 return `${header('選手と、未来の約束を。','能力・実績・年俸を見比べ、ひとりひとりの価値を考える。','TEAM & CONTRACTS')}<div class="toolbar"><div class="segmented"><button data-tab="club" class="${tab==='club'?'selected':''}">所属選手</button><button data-tab="market" class="${tab==='market'?'selected':''}">補強候補</button></div><span class="pill">${off?'契約更改・補強が可能です':'更改期間：10月〜3月'}</span><strong>年俸総額 ${wan(state.players.filter(p=>p.team===0).reduce((n,p)=>n+p.salary,0))} 万円 / 年</strong></div>
 <div class="card table-card"><div class="table-scroll"><table><thead><tr><th>選手 / ポジション</th><th>能力 / 成長性</th><th>人気 / 満足</th><th>コンディション</th><th>今季成績</th><th>年俸 / 契約残</th><th>年俸提示</th></tr></thead><tbody>${list.map(p=>{const m=playerMetrics(p);return `<tr><td><div class="player-name"><span class="player-face">${p.position==='投手'?'⚾':'🧢'}</span><div><b>${esc(p.name)}</b><small>${p.age}歳 · ${p.position}</small></div></div></td><td><b>${p.ability.toFixed(0)}</b> <small>/ ${p.potential}</small><div class="mini-track"><i style="width:${p.ability}%"></i></div></td><td>${p.popularity}<small> / ${Math.round(p.satisfaction)}</small></td><td><span class="pill ${p.injury?'warning':''}">${p.injury?`負傷 ${p.injury}か月`:'良好'}</span><small class="block">疲労 ${Math.round(p.fatigue)}</small></td><td>${p.position==='投手'?`${p.stats.wins}勝 ${p.stats.losses}敗<small class="block">防御率 ${m.era?.toFixed(2)??'—'} / ${Math.floor(p.stats.outs/3)}回</small><small class="block">年俸/勝利 ${wan(m.salaryPerWin)} 万円</small>`:`打率 ${m.average?.toFixed(3)??'—'}<small class="block">${p.stats.hits}安打 / ${p.stats.hr}HR / ${p.stats.rbi}打点</small><small class="block">年俸/安打 ${wan(m.salaryPerHit)} 万円</small>`}</td><td><b>${wan(p.salary)}</b> 万円<small class="block">${p.contract===0?'今オフ満了':`残${p.contract}年`} · 市場 ${wan(marketSalary(p))}万円</small></td><td><form class="contract-form" data-player="${p.id}"><div><input type="number" min="100" max="20000" step="10" value="${Math.round(p.salary/10000)}" aria-label="${esc(p.name)}の提示年俸（万円）" ${off?'':'disabled'}><select aria-label="契約期間" ${off?'':'disabled'}><option value="1">1年</option><option value="2">2年</option><option value="3">3年</option></select></div><button class="small-button" ${off?'':'disabled'}>${tab==='market'?'契約を提示':'更改を提示'}</button></form>${p.offerMessage?`<small class="offer-message">${esc(p.offerMessage)}</small>`:''}</td></tr>`;}).join('')}</tbody></table></div></div><p class="fine-print">年俸/成績は単純比較指標です。守備貢献・出場機会・将来性を評価しきれません。提示は市場目安の80%未満で拒否され、満足度が下がります。</p>`;
}
function plan(){
 const f=forecast(advisorContext(state),draft),base=forecast(advisorContext(state),state.policy);
 return `${header('今月の判断が、次の一歩に。','価格と予算を動かして、球団経営のバランスを探ろう。','MANAGEMENT PLAN')}<div class="plan-layout"><section class="card"><div class="section-heading"><div><h2>価格・予算の設定</h2><p>${f.period} に適用する月次方針</p></div>${icon('sliders')}</div><div class="field-control"><label for="ticket">チケット価格 <b id="ticket-value">${num(draft.ticket)} 円 / 枚</b></label><input type="range" id="ticket" min="1000" max="6000" step="100" value="${draft.ticket}" data-policy="ticket"><div class="range-labels"><span>1,000円 · 来場しやすく</span><span>6,000円 · 単価を重視</span></div><p>値上げは1人あたり売上を増やす一方、来場需要を下げます。</p></div>${[['ads','広告・ファン獲得予算','来月の需要と、中期のファンの熱量に。'],['training','育成予算','若手の能力向上と、疲労の軽減に。']].map(([id,label,desc])=>`<div class="field-control"><label for="${id}">${label}<b id="${id}-value">${wan(draft[id])} 万円 / 月</b></label><input type="range" id="${id}" min="0" max="30000000" step="500000" value="${draft[id]}" data-policy="${id}"><div class="range-labels"><span>0万円</span><span>3,000万円</span></div><p>${desc}</p></div>`).join('')}<div class="section-heading spaced"><div><h2>グッズの仕入れ</h2><p>毎月繰り返す仕入れ数量です。オフの買いすぎに注意。</p></div></div>${state.products.map(p=>`<div class="product-row"><span class="product-icon">${p.icon}</span><div><b>${p.name}</b><small>在庫 ${num(p.stock)}個 · 原価 ${num(p.cost)}円 / 売価 ${num(p.price)}円</small></div><label><input type="number" min="0" max="30000" step="100" value="${draft.orders[p.id]}" data-order="${p.id}" aria-label="${p.name}の月間仕入れ数"> 個</label></div>`).join('')}</section>
 <div><section class="card forecast-card" id="forecast-panel">${forecastPanel(f,base)}</section><section class="note-card"><h3>${icon('book',18)} 利益と現金は、別もの。</h3><p>グッズは仕入れ時に現金を支払い、売れた分を費用にします。売れ残りは在庫資産。利益が出ていても、現金が減ることがあります。</p><button class="text-button" data-action="rules">会計ルールを確認 ${icon('arrow',14)}</button></section><section class="card compact"><h3>運転資金の借入</h3><p>残高 ${wan(state.debt)} 万円 / 上限15,000万円。月利0.5%、元本はこのMVPでは据え置き。</p><button class="secondary" data-action="borrow" ${state.debt>=150000000?'disabled':''}>5,000万円を調達</button></section></div></div>`;
}
function forecastPanel(f,base){return `<span class="pill forecast-pill">${icon('spark',14)} シミュレーション予測</span><h2>次の1か月、どうなる？</h2><p>${f.period} · 現在の設定をもとに試算</p><div class="forecast-number"><span>予測営業利益</span><strong class="${f.profit<0?'negative':''}">${money(f.profit)}</strong><small>感度幅 ${wan(f.low)} 〜 ${wan(f.high)} 万円</small></div><dl class="data-list"><div><dt>予測売上高</dt><dd>${wan(f.revenue)} 万円</dd></div><div><dt>予測月末現金</dt><dd>${wan(f.cash)} 万円</dd></div><div><dt>平均観客数</dt><dd>${num(f.attendance)} 人</dd></div><div><dt>現方針との利益差</dt><dd>${signed(f.profit-base.profit)} 万円</dd></div></dl><p class="assumption">${esc(f.assumptions)}</p><button class="primary full" data-action="adopt">この方針を採用 ${icon('arrow',16)}</button><small class="center block">試算だけでは本編の状態は変わりません</small>`;}
function finance(){
 const row=state.months.find(r=>r.id===selectedMonth)||state.months.at(-1);
 if(!row)return `${header('月次決算','売上・利益・現金。それぞれの動きを確かめよう。','MONTHLY FINANCE')}${empty('決算は、最初の月を終えてから。','経営プランを採用し、ダッシュボードから4月へ進んでください。')}`;
 const q=id=>query(state,{metric:id,from:row.id,to:row.id}),prev=state.months.find(r=>r.year===row.year-1&&r.month===row.month),actual=state.actions.findLast(a=>a.target===row.id&&!a.superseded);
 return `${header('数字から、次の一手を。','利益の理由と、現金の行き先を確かめよう。','MONTHLY FINANCE')}<div class="toolbar"><label>対象月 <select id="month-select">${[...state.months].reverse().map(r=>`<option ${r.id===row.id?'selected':''}>${r.id}</option>`).join('')}</select></label><span class="pill">${row.homeGames} ホーム試合 · ${row.wins}勝 ${row.losses}敗</span><span>前年同月売上差：${prev?`${signed(q('revenue').value-query(state,{metric:'revenue',from:prev.id,to:prev.id}).value)} 万円`:'—（前年データなし）'}</span></div>
 <div class="two-col"><section class="card"><h2>損益計算書 <small>P / L</small></h2><dl class="finance-list">${row.sales.map(r=>`<div><dt>${r.name}売上</dt><dd>${wan(r.amount)} 万円</dd></div>`).join('')}<div class="total"><dt>売上高 ${metricButton('revenue')}</dt><dd>${wan(q('revenue').value)} 万円</dd></div>${row.costs.slice(0,2).map(r=>`<div><dt>${r.name}</dt><dd>− ${wan(r.amount)} 万円</dd></div>`).join('')}<div class="subtotal"><dt>粗利益 ${metricButton('grossProfit')}</dt><dd>${wan(q('grossProfit').value)} 万円</dd></div>${row.costs.slice(2).map(r=>`<div><dt>${r.name}</dt><dd>− ${wan(r.amount)} 万円</dd></div>`).join('')}<div class="total"><dt>営業利益 ${metricButton('operatingProfit')}</dt><dd>${wan(q('operatingProfit').value)} 万円</dd></div><div><dt>借入利息（営業外）</dt><dd>− ${wan(row.interest)} 万円</dd></div><div class="subtotal"><dt>税引前利益（税なし）</dt><dd>${wan(q('operatingProfit').value-row.interest)} 万円</dd></div></dl></section>
 <div><section class="card"><h2>現金の動き <small>CASH FLOW</small></h2><dl class="finance-list"><div><dt>月初現金（別途の借入反映後）</dt><dd>${wan(row.startCash)} 万円</dd></div><div><dt>売上入金</dt><dd>+ ${wan(row.inflow)} 万円</dd></div><div><dt>グッズ仕入れ支出</dt><dd>− ${wan(row.products.reduce((n,p)=>n+p.purchaseCash,0))} 万円</dd></div><div><dt>その他支出（利息含む）</dt><dd>− ${wan(row.outflow-row.products.reduce((n,p)=>n+p.purchaseCash,0))} 万円</dd></div><div class="total"><dt>月末現金 ${metricButton('cash')}</dt><dd>${wan(row.endCash)} 万円</dd></div></dl><div class="explain-box">営業利益 ${wan(q('operatingProfit').value)} − 在庫増加 ${wan(row.inventoryEnd-row.inventoryStart)} − 利息 ${wan(row.interest)} ＝ 現金増減 ${wan(q('cashChange').value)} 万円</div></section><section class="card spaced"><h2>予算（採用時予測）と実績</h2>${actual?.forecast?`<dl class="data-list"><div><dt>営業利益：予測 → 実績</dt><dd>${wan(actual.forecast.profit)} → ${wan(q('operatingProfit').value)} 万円</dd></div><div><dt>予測からの差</dt><dd>${signed(q('operatingProfit').value-actual.forecast.profit)} 万円</dd></div></dl><p class="fine-print">季節・試合結果・需要変動の影響を含むため、差分を施策の効果と断定しません。</p>`:'<p>この月は採用時の予測記録がありません。経営プランで方針を採用すると記録されます。</p>'}</section></div></div>
 <section class="card spaced"><h2>グッズ在庫台帳</h2><div class="table-scroll"><table><thead><tr><th>商品</th><th>期首</th><th>仕入れ</th><th>販売</th><th>期末</th><th>売上</th><th>売上原価</th><th>在庫金額</th><th>欠品需要</th></tr></thead><tbody>${row.products.map(p=>`<tr><td>${p.name}</td><td>${num(p.opening)}</td><td>${num(p.purchased)}</td><td>${num(p.sold)}</td><td>${num(p.closing)}</td><td>${wan(p.sales)}</td><td>${wan(p.cogs)}</td><td>${wan(p.closing*p.cost)}</td><td>${num(p.unmet)}個</td></tr>`).join('')}</tbody></table></div></section><section class="card spaced"><h2>経営指標 <small>共通セマンティックレイヤー</small></h2><div class="metric-grid">${['goodsProfit','payrollRatio','attendance','occupancy','revenuePerFan','turnover'].map(id=>`<div><span>${METRICS[id].name} ${metricButton(id)}</span><b>${fmt(q(id).value,q(id).unit)}</b></div>`).join('')}</div></section>`;
}
function season(){
 const years=[...new Set([state.year,...state.seasons.map(s=>s.year)])].sort((a,b)=>b-a),year=selectedYear||state.year, archive=state.seasons.find(s=>s.year===year),table=standings(state,year),months=state.months.filter(r=>r.id>=`${year}-04`&&r.id<=`${year+1}-03`),q=metric=>query(state,{metric,from:`${year}-04`,to:`${year+1}-03`}),players=archive?.players||state.players.filter(p=>p.team===0),games=state.games.filter(g=>g.year===year&&(g.home===0||g.away===0));
 return `${header('積み重ねた、ひとつのシーズン。','一勝の価値も、一年の経営も。ベアーズの歩みを振り返ろう。','SEASON REPORT')}<div class="toolbar"><select id="year-select">${years.map(y=>`<option value="${y}" ${y===year?'selected':''}>${y} シーズン</option>`).join('')}</select><span class="pill">${archive?'野球シーズン確定':'野球シーズン進行前 / 進行中'}</span><span>会計年度 ${year}年4月〜${year+1}年3月 · ${months.length}/12か月</span></div><div class="two-col"><section class="card"><h2>こもれびリーグ 順位表</h2><table><thead><tr><th>順位</th><th>球団</th><th>勝</th><th>敗</th><th>勝率</th><th>得失点差</th></tr></thead><tbody>${table.map((r,i)=>`<tr class="${r.id===0?'our-team':''}"><td>${r.w+r.l?i+1:'—'}</td><td>${r.name}</td><td>${r.w}</td><td>${r.l}</td><td>${r.w+r.l?(r.w/(r.w+r.l)).toFixed(3):'—'}</td><td>${r.runs-r.allowed}</td></tr>`).join('')}</tbody></table></section><section class="card"><h2>年間決算 <small>${months.length===12?'確定':'年度途中'}</small></h2><dl class="finance-list">${['revenue','grossProfit','operatingProfit','payroll','cash'].map(id=>`<div class="${id==='operatingProfit'?'total':''}"><dt>${METRICS[id].name} ${metricButton(id)}</dt><dd>${fmt(q(id).value,q(id).unit)}</dd></div>`).join('')}</dl></section></div><section class="card spaced"><h2>選手のシーズン成績 <small>${archive?'9月末の確定記録':'現在の成績'}</small></h2><div class="table-scroll"><table><thead><tr><th>選手</th><th>出場</th><th>打数</th><th>安打</th><th>本塁打</th><th>得点</th><th>打点</th><th>勝 / 敗</th><th>投球回</th><th>失点</th></tr></thead><tbody>${players.map(p=>`<tr><td>${esc(p.name)} <small>${p.position}</small></td>${['games','ab','hits','hr','runs','rbi'].map(k=>`<td>${p.stats[k]}</td>`).join('')}<td>${p.stats.wins} / ${p.stats.losses}</td><td>${Math.floor(p.stats.outs/3)}${p.stats.outs%3?'.'+p.stats.outs%3:''}</td><td>${p.stats.er}</td></tr>`).join('')}</tbody></table></div></section><section class="card spaced"><h2>試合ログ <small>最新18試合 / ${games.length}試合</small></h2><div class="game-log">${games.slice(-18).reverse().map(g=>`<div><span>${g.month}/${g.day}</span><span>${TEAM_NAMES[g.home]} ${g.homeRuns} − ${g.awayRuns} ${TEAM_NAMES[g.away]}</span><b class="${(g.home===0?g.homeRuns>g.awayRuns:g.awayRuns>g.homeRuns)?'positive':'negative'}">${(g.home===0?g.homeRuns>g.awayRuns:g.awayRuns>g.homeRuns)?'WIN':'LOSE'}</b></div>`).join('')||'<p>開幕前です。</p>'}</div></section>`;
}
function advisor(){
 return `${header('ひとりで悩まない、球団経営。','根拠を確かめ、仮説を立て、次の一手を一緒に考えよう。','YOUR DATA PARTNER')}<div class="advisor-banner"><div class="advisor-avatar">${icon('spark',32)}</div><div><h2>こもれびのAI参謀</h2><p>ルールベースのデモ · 外部API接続なし · 方針はあなたが採用してから反映</p></div><span class="pill">SEMANTIC LAYER CONNECTED</span></div><div class="question-chips">${['現金と売上の差を知りたい','グッズは何個仕入れる？','チケットを値上げすると？','優勝案と黒字案を比較'].map(q=>`<button data-question="${q}">${q} ${icon('arrow',14)}</button>`).join('')}</div><form id="advisor-form" class="question-form"><input name="question" aria-label="参謀への相談" placeholder="球団の経営について相談する…" required maxlength="500"><button class="primary">分析する ${icon('spark',16)}</button></form><div id="advice-result">${advice?adviceHtml():empty('参謀と、最初の作戦会議。','相談内容を選ぶと、共通の指標と明示した前提から提案を作ります。')}</div>`;
}
function adviceHtml(){
 const a=advice;
 return `<section class="card advice-detail"><span class="pill forecast-pill">提案 · ${esc(a.label)}</span><h2>${esc(a.title)}</h2><p class="question-echo">相談：${esc(a.question)}</p><div class="advice-section"><h3><span class="step">01</span> 確認できた事実 <small>${a.period?esc(a.period):'決算データなし'}</small></h3><div class="evidence-grid">${a.facts.map(f=>`<div>${esc(f.text)} ${metricButton(f.metric)}</div>`).join('')||'<p>月次決算はまだありません。</p>'}</div><p>${esc(a.lack)}</p><button class="text-button" data-page="finance">根拠を月次決算で確認 ${icon('arrow',14)}</button></div><div class="advice-section"><h3><span class="step">02</span> 仮説・推測</h3><p>${esc(a.hypothesis)}</p></div><div class="advice-section"><h3><span class="step">03</span> 推奨施策と代替案</h3><p><b>推奨：</b>${esc(a.action)}</p><p><b>代替：</b>${esc(a.alternative)}</p></div><div class="advice-section"><h3><span class="step">04</span> シミュレーション予測 <small>${a.predicted.period}</small></h3><div class="comparison"><div><span>現方針の営業利益</span><strong>${money(a.baseline.profit)}</strong></div><span>${icon('arrow')}</span><div><span>提案採用時の営業利益</span><strong>${money(a.predicted.profit)}</strong></div></div><p>${esc(a.comparison)}</p><p>利益の感度幅：${wan(a.predicted.low)}〜${wan(a.predicted.high)} 万円</p><details><summary>採用する設定を見る</summary><p>チケット ${num(a.policy.ticket)}円 / 広告 ${wan(a.policy.ads)}万円 / 育成 ${wan(a.policy.training)}万円</p><p>${state.products.map(p=>`${p.name}：${a.policy.orders[p.id]}個`).join('、')}</p></details><p class="assumption">${esc(a.predicted.assumptions)}</p><p><b>リスク：</b>${esc(a.risk)}</p></div><div class="advice-section"><h3><span class="step">05</span> 実行後の検証</h3><p>${esc(a.verify)}</p></div><button class="primary" data-action="adopt-advice">この提案を採用する ${icon('arrow',17)}</button><small>採用内容と予測を施策ノートに記録します</small></section>`;
}
function history(){
 return `${header('仮説を、学びに変える。','予測と実績を並べて、次の意思決定を磨こう。','EXPERIMENT NOTEBOOK')}${state.actions.length?[...state.actions].reverse().map(a=>`<section class="card action-card"><div class="section-heading"><div><span class="eyebrow">${esc(a.target||a.period)}</span><h2>${esc(a.title)}</h2></div><span class="pill ${a.superseded?'warning':''}">${a.kind==='finance'?'財務入金':a.superseded?'後の方針で上書き':a.actual?'検証可能':'翌月を待っています'}</span></div>${a.kind==='finance'?`<p>${esc(a.note)}</p>`:`<p>狙い：${esc(a.title==='経営方針を変更'?'価格・予算・在庫のバランスを改善する':a.title)}</p><p class="fine-print">採用設定：チケット ${num(a.policy.ticket)}円、広告 ${wan(a.policy.ads)}万円、育成 ${wan(a.policy.training)}万円。${a.superseded?'この予測は実行対象から外れています。':''}</p><table><thead><tr><th>検証指標</th><th>予測</th><th>実績</th><th>差分</th></tr></thead><tbody>${[['profit','営業利益'],['revenue','売上高'],['cash','月末現金']].map(([key,label])=>`<tr><td>${label}</td><td>${wan(a.forecast[key])} 万円</td><td>${a.actual&&!a.superseded?wan(a.actual[key])+' 万円':'—'}</td><td>${a.actual&&!a.superseded?signed(a.actual[key]-a.forecast[key])+' 万円':'—'}</td></tr>`).join('')}</tbody></table>${a.actual&&!a.superseded?`<div class="explain-box"><b>${a.actual.profit>=a.forecast.low&&a.actual.profit<=a.forecast.high?'営業利益は想定幅の範囲内でした。':'営業利益は想定幅から外れました。'}</b><p>${esc(a.review)}</p><p>予測中心値以上：${a.actual.profit>=a.forecast.profit?'達成':'未達'}。対照実験ではないため、因果効果は未確認です。</p></div>`:`<p class="assumption">${esc(a.forecast.assumptions)}</p>`}`}</section>`).join(''):empty('小さな仮説が、球団を変える。','経営プランや参謀の提案を採用すると、狙い・設定・予測がここに残ります。')}`;
}
function dialog(content){const el=document.querySelector('#metric-dialog');el.innerHTML=`<button class="dialog-close" aria-label="閉じる">×</button>${content}`;el.querySelector('button').onclick=()=>el.close();el.showModal();}
function showMetric(id){const d=METRICS[id],m=latestMetrics(state)[id];dialog(`<span class="eyebrow">SEMANTIC DEFINITION</span><h2>${d.name}</h2><p>${d.description}</p><div class="formula">${esc(d.formula)}</div><dl class="data-list"><div><dt>単位</dt><dd>${d.unit}（円は画面で万円換算）</dd></div><div><dt>集計粒度</dt><dd>月次 / 会計年度</dd></div><div><dt>分析軸</dt><dd>月・年度${d.dimensions.length?'・'+d.dimensions.map(x=>({product:'商品',category:'売上区分'})[x]).join('・'):''}</dd></div><div><dt>最新確定値 ${m.from||''}</dt><dd>${fmt(m.value,d.unit)}${d.unit==='円'&&m.value!==null?`<small class="block">正確な値：${num(m.value)} 円</small>`:''}</dd></div></dl><p class="fine-print">画面と参謀は同じ登録済み計算を呼びます。欠損・ゼロ分母は「—」。率は合計から計算し、残高は最終月を参照。月IDで重複除去し、試合と会計明細を結合しません。</p>`);}
async function ask(question){
 busy=true;toast('共通指標から分析しています…');
 try{advice=await advisorProvider.analyze(advisorContext(state),question);page='advisor';render();}
 catch(e){toast(e.message);}finally{busy=false;}
}
function bind(){
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=e=>{e.preventDefault();page=b.dataset.page;render();window.scrollTo(0,0);});
 document.querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>showMetric(b.dataset.metric));
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
 document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>ask(b.dataset.question));
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});
 document.querySelectorAll('[data-policy],[data-order]').forEach(input=>input.oninput=()=>{
   if(input.dataset.policy){draft[input.dataset.policy]=Number(input.value);document.querySelector(`#${input.id}-value`).textContent=input.id==='ticket'?`${num(draft.ticket)} 円 / 枚`:`${wan(draft[input.id])} 万円 / 月`;}
   else draft.orders[input.dataset.order]=Number(input.value);
   const panel=document.querySelector('#forecast-panel');panel.innerHTML=forecastPanel(forecast(advisorContext(state),draft),forecast(advisorContext(state),state.policy));panel.querySelector('button').onclick=()=>action('adopt');
 });
 document.querySelectorAll('.contract-form').forEach(form=>form.onsubmit=e=>{e.preventDefault();try{state=offerContract(state,form.dataset.player,Math.round(Number(form.querySelector('input').value)*10000),Number(form.querySelector('select').value));advice=null;persist();render();toast(state.notices[0]);}catch(err){toast(err.message);}});
 const af=document.querySelector('#advisor-form');if(af)af.onsubmit=e=>{e.preventDefault();ask(new FormData(af).get('question'));};
 const month=document.querySelector('#month-select');if(month)month.onchange=()=>{selectedMonth=month.value;render();};
 const year=document.querySelector('#year-select');if(year)year.onchange=()=>{selectedYear=Number(year.value);render();};
}
async function action(name){
 try{
 if(name==='advance'){
   if(busy)return;busy=true;state=advance(state);draft=structuredClone(state.policy);advice=await advisorProvider.analyze(advisorContext(state),'全体');persist();render();toast(`${state.month}月の決算が届きました${state.notices.length?'。お知らせも確認してください。':'。'}`);
 }else if(name==='adopt'||name==='adopt-advice'){
   const p=name==='adopt-advice'?advice.policy:draft,f=forecast(advisorContext(state),p);
   state=adoptPolicy(state,p,f,name==='adopt-advice'?advice.title:'経営方針を変更');draft=structuredClone(state.policy);persist();render();toast(`${f.period}の方針を採用し、予測を記録しました。`);
 }else if(name==='borrow'){state=borrow(state);advice=null;persist();render();toast('5,000万円を調達し、財務履歴に記録しました。');}
 else if(name==='rules'){dialog(`<span class="eyebrow">THE RULEBOOK</span><h2>数字の意味が、共通だから。</h2><p>画面・試算の比較・参謀の根拠を、読み解くためのルール。</p><ol class="rules">${RULES.map(r=>`<li>${r}</li>`).join('')}</ol><h3>選手別指標（シーズン粒度）</h3><dl class="data-list">${Object.values(PLAYER_METRICS).map(m=>`<div><dt>${m.name}<small class="block">${m.caveat}</small></dt><dd>${m.formula}</dd></div>`).join('')}</dl><p>試算は公開された現状と前提を使い、本編の乱数や未来の結果を参照しません。予測の計算モデルと、確定した指標の集計は別の役割です。</p>`);}
 else if(name==='new-game'){dialog(`<span class="eyebrow">A NEW SEASON</span><h2>はじめから遊ぶ</h2><p>2026年3月の開幕準備から始めます。現在の進行はブラウザにバックアップとして1件残します。</p><div class="spaced"><button class="primary" id="confirm-new">新しい球団を始める</button> <button class="secondary" id="restore-backup">前回のバックアップに戻る</button></div>`);document.querySelector('#confirm-new').onclick=()=>{try{localStorage.setItem(KEY+'-backup',serialize(state));state=initialState();draft=structuredClone(state.policy);advice=null;selectedYear=null;selectedMonth=null;page='dashboard';persist();document.querySelector('#metric-dialog').close();render();toast('開幕前から新しい経営を始めました。');}catch{toast('バックアップを保存できないため、新規開始を中止しました。');}};document.querySelector('#restore-backup').onclick=async()=>{try{const raw=localStorage.getItem(KEY+'-backup');if(!raw)throw Error('バックアップはまだありません。');const restored=deserialize(raw);localStorage.setItem(KEY+'-backup',serialize(state));state=restored;draft=structuredClone(state.policy);advice=await advisorProvider.analyze(advisorContext(state),'全体');page='dashboard';selectedYear=null;selectedMonth=null;persist();document.querySelector('#metric-dialog').close();render();toast('バックアップから復元しました。');}catch(e){toast(e.message);}};}
 else if(name==='export'){persist();const blob=new Blob([serialize(state)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`komorebi-${periodKey(state.year,state.month)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('セーブデータを書き出しました。');}
 else if(name==='import')document.querySelector('#save-file').click();
 }catch(e){toast(e.message);}finally{busy=false;}
}
document.querySelector('#save-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10000000)throw Error('10MB以下のセーブファイルを選んでください。');const restored=deserialize(await file.text());state=restored;draft=structuredClone(state.policy);advice=null;selectedMonth=null;selectedYear=null;persist();render();toast('同じ状態から再開しました。');}catch(err){toast(err.message);}e.target.value='';};
if(state.months.length)advice=await advisorProvider.analyze(advisorContext(state),'全体');
render();
